package com.bank.reporting.repository;

import com.bank.reporting.model.Transaction;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;

public interface TransactionRepository extends JpaRepository<Transaction, String> {

    List<Transaction> findByTxnDate(LocalDate date);

    @Query("SELECT COALESCE(SUM(t.amount), 0) FROM Transaction t WHERE t.txnDate = :date AND t.type = :type")
    BigDecimal sumByDateAndType(LocalDate date, String type);

    long countByTxnDate(LocalDate date);
}
