package com.bank.reporting.controller;

import com.bank.reporting.dto.EodReport;
import com.bank.reporting.service.*;
import lombok.RequiredArgsConstructor;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.web.bind.annotation.*;
import java.math.BigDecimal;
import java.time.LocalDate;

@RestController
@RequestMapping("/api/v1/reports")
@RequiredArgsConstructor
public class ReportController {

    private final EodReportService reportService;
    private final LiveTransactionService liveService;

    @GetMapping("/eod/{date}")
    public EodReport eodReport(@PathVariable @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate date) {
        return reportService.generateReport(date);
    }

    // Simulate live deposit DURING report generation
    @PostMapping("/live-deposit")
    public String deposit(@RequestParam String accountId, @RequestParam BigDecimal amount) {
        return liveService.processDeposit(accountId, amount);
    }
}
