package com.bank.reporting.service;

import com.bank.reporting.dto.EodReport;
import com.bank.reporting.repository.TransactionRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.*;
import org.mockito.junit.jupiter.MockitoExtension;
import java.math.BigDecimal;
import java.time.LocalDate;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class EodReportServiceTest {

    @Mock TransactionRepository txnRepo;
    @InjectMocks EodReportService reportService;

    @Test
    void shouldGenerateConsistentReport() {
        LocalDate date = LocalDate.of(2024, 1, 15);
        when(txnRepo.countByTxnDate(date)).thenReturn(5L);
        when(txnRepo.sumByDateAndType(date, "CREDIT")).thenReturn(new BigDecimal("350000"));
        when(txnRepo.sumByDateAndType(date, "DEBIT")).thenReturn(new BigDecimal("65000"));

        EodReport report = reportService.generateReport(date);

        assertThat(report.totalTransactions()).isEqualTo(5);
        assertThat(report.totalCredits()).isEqualByComparingTo("350000");
        assertThat(report.totalDebits()).isEqualByComparingTo("65000");
        assertThat(report.netFlow()).isEqualByComparingTo("285000");
    }
}
